import {
  Collection,
  Header,
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  ListBoxLoadMoreItem as AriaListBoxLoadMoreItem,
  ListBoxSection as AriaListBoxSection,
} from "react-aria-components";
import type {
  ListBoxItemProps as AriaListBoxItemProps,
  ListBoxLoadMoreItemProps as AriaListBoxLoadMoreItemProps,
  ListBoxProps as AriaListBoxProps,
} from "react-aria-components";
import { createContext, useContext } from "react";
import type { ComponentProps, ReactNode, Ref } from "react";
import { Check } from "./icons";
import "./ListBox.css";

export type ListBoxIndicator = "fill" | "check";

const ListBoxIndicatorContext = createContext<ListBoxIndicator>("fill");
// The list's variant, which each row stamps on itself so a grouped row is styled on its own element.
const ListBoxVariantContext = createContext<"flat" | "grouped">("flat");

export interface ListBoxProps<T extends object = object>
  extends Omit<AriaListBoxProps<T>, "className"> {
  /**
   * `flat` (default): the rows on whatever surface holds the list, each bounded only by its fill.
   * `grouped`: one box around all the rows (the surface pair's corner, a decorative edge), the rows
   * parted by hairlines, for a short choice sheet whose rows belong together.
   *
   * @default "flat"
   */
  variant?: "flat" | "grouped";
  /**
   * How a selected option shows it is selected. `fill` (default) paints the row with the selection
   * fill. `check` paints no fill: the selected row's text takes the brand ink and the emphasized
   * weight, and a check stands at its trailing edge, while an unselected row is plain text. The
   * look of a sort sheet, where the list is the whole surface and a fill would read as a button.
   *
   * @default "fill"
   */
  indicator?: ListBoxIndicator;
  /** Additional class. sd-list-box is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ListBox<T extends object = object>({
  variant = "flat",
  indicator = "fill",
  className,
  renderEmptyState,
  ...props
}: ListBoxProps<T>) {
  return (
    <ListBoxIndicatorContext.Provider value={indicator}>
      <ListBoxVariantContext.Provider value={variant}>
      <AriaListBox
        {...props}
        data-indicator={indicator}
        data-variant={variant}
        /* An empty state given as words is a text part of its own: a bare string took no type role,
           so it stood at 0 while every other text stands one inset in (component-contract.md §6
           rule 8). Medium at every size, as a collection's empty message is (§7), muted as an empty
           line is (text colour roles, row 4). Words are wrapped; an element the consumer drew (a
           ComboBox's own empty part) is its own. */
        renderEmptyState={
          renderEmptyState &&
          ((p) => {
            const empty = renderEmptyState(p);
            return typeof empty === "string" || typeof empty === "number" ? <div className="sd-list-box__empty sd-type-body-medium">{empty}</div> : empty;
          })
        }
        className={className ? `sd-list-box ${className}` : "sd-list-box"}
      />
      </ListBoxVariantContext.Provider>
    </ListBoxIndicatorContext.Provider>
  );
}

export interface ListBoxItemProps<T extends object = object>
  extends Omit<AriaListBoxItemProps<T>, "className"> {
  /** Leading icon (optional). Pass `textValue` when children aren't plain text. */
  icon?: ReactNode;
  /**
   * A preview above the option's name, which makes the option a tile: a thumbnail, an artwork, a
   * sample. Its corner and clip are the consumer's, through `Media`. Decorative: the option is named
   * by its text alone.
   */
  media?: ReactNode;
  /** Marks the option unavailable: disabled, on the neutral subtle fill with a muted label, and this
   *  reason at its trailing edge, e.g. "가입 불가". The reason is part of the option's text, so it is
   *  read in the option's accessible name: why it cannot be chosen, not only that it cannot. */
  unavailableLabel?: string;
  /** Additional class. sd-list-box__item is always retained. */
  className?: string;
  /** Passed to the underlying option DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export function ListBoxItem<T extends object = object>({
  icon,
  media,
  unavailableLabel,
  className,
  children,
  textValue,
  isDisabled,
  ...props
}: ListBoxItemProps<T>) {
  const indicator = useContext(ListBoxIndicatorContext);
  const variant = useContext(ListBoxVariantContext);
  // Under `indicator="check"` the selected row carries its state in its own text: the emphasized
  // twin of the row's type role, as a NavItem label under `indicator="ink"` does.
  const typeClass = (isSelected: boolean) =>
    indicator === "check" && isSelected ? "sd-type-body-medium-emphasized" : "sd-type-body-medium";
  return (
    <AriaListBoxItem
      {...props}
      // Children render via a function (icon + label), so RAC can't auto-derive textValue
      // and filtering/typeahead would break. Re-derive from string children (matches
      // GridListItem / MenuItem); pass an explicit `textValue` when children aren't plain text.
      textValue={textValue || (typeof children === "string" ? children : undefined)}
      data-media={media != null || undefined}
      data-variant={variant === "grouped" ? variant : undefined}
      // Stamped on the row, as the variant is, so the check look is styled on the row's own element.
      data-indicator={indicator === "check" ? indicator : undefined}
      isDisabled={isDisabled || unavailableLabel != null}
      data-unavailable={unavailableLabel != null || undefined}
      className={({ isSelected }) =>
        className
          ? `sd-list-box__item ${typeClass(isSelected)} ${className}`
          : `sd-list-box__item ${typeClass(isSelected)}`
      }
    >
      {(renderProps) => (
        <>
          {media != null && (
            <span className="sd-list-box__item-media" aria-hidden="true">
              {media}
            </span>
          )}
          {icon && (
            <span className="sd-list-box__item-icon" aria-hidden="true">
              {icon}
            </span>
          )}
          {(unavailableLabel != null || variant === "grouped") && typeof children === "string" ? (
            // A grouped row pads itself, which outweighs its own role's inset, and the reason is a
            // text of its own, which zeroes the row's (rule 8: a text holding another text stands at
            // 0). Either way the label takes its own element and the inset.
            <span className={`sd-list-box__item-label ${typeClass(renderProps.isSelected)}`}>
              {children}
            </span>
          ) : typeof children === "function" ? (
            children(renderProps)
          ) : (
            children
          )}
          {unavailableLabel != null && (
            <span className="sd-list-box__item-reason sd-type-caption-medium">{unavailableLabel}</span>
          )}
          {/* Decorative: React Aria exposes the selection as aria-selected. */}
          {indicator === "check" && renderProps.isSelected && (
            <span className="sd-list-box__item-check" aria-hidden="true">
              <Check size="1em" />
            </span>
          )}
        </>
      )}
    </AriaListBoxItem>
  );
}

type AriaListBoxSectionProps = ComponentProps<typeof AriaListBoxSection>;

export interface ListBoxSectionProps
  extends Omit<AriaListBoxSectionProps, "className" | "children"> {
  /** Optional section heading. */
  title?: ReactNode;
  /** ListBoxItem children or a dynamic collection renderer. */
  children?: AriaListBoxSectionProps["children"];
  /** Additional class. sd-list-box__section is always retained. */
  className?: string;
}

export function ListBoxSection({
  title,
  children,
  className,
  ...props
}: ListBoxSectionProps) {
  return (
    <AriaListBoxSection
      {...props}
      className={
        className ? `sd-list-box__section ${className}` : "sd-list-box__section"
      }
    >
      {/* One rung below the items it heads — CONTRASTIVE, per naming-convention.md. */}
      {title && (
        <Header className="sd-list-box__section-header sd-type-label-small">
          {title}
        </Header>
      )}
      {typeof children === "function" ? <Collection>{children}</Collection> : children}
    </AriaListBoxSection>
  );
}

export interface ListBoxLoadMoreItemProps
  extends Omit<AriaListBoxLoadMoreItemProps, "className" | "children"> {
  /** Loading-row content — required; the .tsx bakes no default text (contract §7b: no
   *  default content, and a hardcoded "Loading…" would ship untranslated English). */
  children: AriaListBoxLoadMoreItemProps["children"];
  /** Additional class. sd-list-box__load-more is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ListBoxLoadMoreItem({
  children,
  className,
  isLoading = true,
  ...props
}: ListBoxLoadMoreItemProps) {
  return (
    <AriaListBoxLoadMoreItem
      {...props}
      isLoading={isLoading}
      className={
        className
          ? `sd-list-box__load-more sd-type-caption-medium ${className}`
          : "sd-list-box__load-more sd-type-caption-medium"
      }
    >
      {children}
    </AriaListBoxLoadMoreItem>
  );
}

/* Flat by default — a content region, not a box. On its own it is a bare flat list; the
   surface (background/border/radius) is owned only by whatever composes it — a Popover in
   Select/ComboBox, a Dialog in CommandMenu. Matches Calendar/ScrollArea and avoids
   container-in-container. */
.sd-list-box {
  display: flex;
  flex-direction: column;
  gap: var(--sd-list-box-gap);
  outline: none;
}

/* A horizontal list (`orientation="horizontal"`): its options run along a row, the way React Aria's
   arrow keys then move through them. Each option's fill bleeds sideways by its overhang, so two
   neighbours stand twice that apart or their fills overlap; a column needs none, its fills keep to
   their own rows. */
.sd-list-box[data-orientation="horizontal"] {
  flex-direction: row;
  column-gap: calc(2 * var(--sd-list-box-item-state-layer-overhang));
}

/* A grid (`layout="grid"`): options auto-fill columns no narrower than the column token, as an asset
   panel lays out its tiles; the arrow keys then move in two dimensions. Columns part by twice the
   fill's overhang, as a horizontal list's options do; rows keep the list's own gap, since a fill
   bleeds only sideways. */
.sd-list-box[data-layout="grid"] {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(var(--sd-list-box-grid-min-column-width), 1fr));
  column-gap: calc(2 * var(--sd-list-box-item-state-layer-overhang));
}

.sd-list-box[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* grouped (`variant="grouped"`): one box around all the rows, which part by hairlines, the look of a
   short choice sheet. The box spends the surface pair at the medium tier (its corner here, its rows'
   inline padding) and clips the rows' fills to its corner, so a row is a box's content rather than a
   bleed row: its fill stays inside it and its text stands one inset in from the row's padding. */
.sd-list-box[data-variant="grouped"] {
  gap: 0;
  border: var(--sd-list-box-grouped-border-width) solid var(--sd-list-box-grouped-border);
  border-radius: var(--sd-list-box-grouped-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  overflow: hidden;
}

.sd-list-box__item {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: var(--sd-list-box-item-gap);
  min-height: var(--sd-list-box-item-min-height);
  /* A row whose only paint is its fill, so its content sits at 0 on the one start line and the fill
     bleeds past it instead (component-contract.md §6 rule 8; Collapsible is the reference shape).
     Select and ComboBox rows are their own parts and keep their padding inside the popover. */
  padding-block: var(--sd-list-box-item-padding-block);
  border-radius: var(--sd-list-box-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-list-box-item-foreground);
  /* The fill lives on the ::before so it can bleed; the box itself paints nothing. */
  background: transparent;
  /* The fill the ::before paints: none at rest, the selected fill below. */
  --sd-list-box-item-fill-current: transparent;
  cursor: pointer;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-list-box-item-state-hover-current: var(--sd-state-hover);
  --sd-list-box-item-state-pressed-current: var(--sd-state-pressed);
  /* The description's ink, raised to the item's own while the row is hovered or pressed (below). */
  --sd-list-box-item-description-current: var(--sd-list-box-item-description-foreground);
}

/* The selected fill, on a layer rather than the box so it bleeds with the state layer.
   Under the content: the root isolates, so -1 stays inside it (component-contract.md § 6). */
/* A tile (`media`): the preview over the name, as an asset panel lists its items. The fill still
   bleeds by the overhang, so it frames the preview as it frames a row. */
.sd-list-box__item[data-media] {
  flex-direction: column;
  align-items: stretch;
}
.sd-list-box__item-media {
  display: block;
}

.sd-list-box__item::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-list-box-item-state-layer-overhang));
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-list-box-item-fill-current);
  pointer-events: none;
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* Interaction state-layer: hover/pressed tint composites over the selected fill via a
   pointer-events-none ::after overlay, so a hovered+selected item keeps its selection color
   (ADR-0009 state-layer). Later in tree order than the ::before, so it paints above it at the
   same z-index, and it bleeds by the same overhang. */
.sd-list-box__item::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: calc(-1 * var(--sd-list-box-item-state-layer-overhang));
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-list-box__item[data-hovered]::after,
.sd-list-box__item[data-focused]::after {
  background: var(--sd-list-box-item-state-hover-current);
}
.sd-list-box__item[data-pressed]::after {
  background: var(--sd-list-box-item-state-pressed-current);
}

.sd-list-box__item[data-selected] {
  --sd-list-box-item-fill-current: var(--sd-list-box-item-background-selected);
  --sd-list-box-item-state-hover-current: var(--sd-state-hover-selected);
  --sd-list-box-item-state-pressed-current: var(--sd-state-pressed-selected);
}

/* `indicator="check"`: no fill, resting or selected. The selected row carries its state in its own
   text, the brand ink and the emphasized weight (ListBox.tsx), and in a trailing check that takes
   the same ink. Hover, focus and press wash the row as they wash an unselected one, and raise the ink
   to the row's own, since brand ink falls under its floor over the surface wash
   (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-list-box__item[data-indicator="check"][data-selected] {
  --sd-list-box-item-fill-current: transparent;
  --sd-list-box-item-state-hover-current: var(--sd-state-hover);
  --sd-list-box-item-state-pressed-current: var(--sd-state-pressed);
  color: var(--sd-list-box-item-indicator-check-foreground);
}
.sd-list-box__item[data-indicator="check"][data-selected][data-hovered],
.sd-list-box__item[data-indicator="check"][data-selected][data-focused],
.sd-list-box__item[data-indicator="check"][data-selected][data-pressed] {
  color: var(--sd-list-box-item-foreground);
}

/* The check, pinned to the row's trailing edge by an auto margin, so the label keeps the free width. */
.sd-list-box__item-check {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  margin-inline-start: auto;
  font-size: var(--sd-list-box-item-icon-size);
}

/* A row of a grouped list (ListBox.tsx stamps the list's variant on each row, so this is a same-element
   rule): a box's content rather than a bleed row. It pads itself as a surface does, which outweighs
   its own role's inset, so its label takes its own element and the inset from that element's role
   (component-contract.md §6 rule 8), as a Card's title does inside the Card's padding; its fill
   stays inside it, square, and the list's box clips it to its corner; a hairline parts it from the
   row above, none over the first. A flat row declares no inline padding at all, so its type role
   gives its text the inset. */
.sd-list-box__item[data-variant="grouped"] {
  min-height: var(--sd-list-box-grouped-item-min-height);
  padding-inline: var(--sd-list-box-grouped-item-padding-inline);
  border-block-start: var(--sd-list-box-grouped-border-width) solid var(--sd-list-box-grouped-divider);
  border-radius: 0;
}
.sd-list-box__item[data-variant="grouped"]:first-child {
  border-block-start-width: 0;
}
.sd-list-box__item[data-variant="grouped"]::before,
.sd-list-box__item[data-variant="grouped"]::after {
  inset-inline: 0;
}

.sd-list-box__item[data-disabled]:not([data-unavailable]) {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* An unavailable option (`unavailableLabel`): disabled, and saying why. It keeps full opacity on the
   neutral subtle fill with a muted label, and the reason stands at its trailing edge, so the row
   reads as present but closed rather than faded out. */
.sd-list-box__item[data-unavailable] {
  --sd-list-box-item-fill-current: var(--sd-list-box-item-unavailable-background);
  /* The fill's own wash, should a state ever reach a disabled row (contract §6 rule 7). */
  --sd-list-box-item-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-list-box-item-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
  color: var(--sd-list-box-item-unavailable-foreground);
  cursor: not-allowed;
}
.sd-list-box__item-reason {
  flex: 0 0 auto;
  margin-inline-start: auto;
  color: var(--sd-list-box-item-reason-foreground);
}

/* `section-gap` parts one SECTION from the next and nothing else. Spent as the section's own
   flex `gap` it landed between EVERY child, which pushed the header away from the group it
   labels and toward the group above it — measured in every brand, the header sat closer to the
   previous section's last row than to the first row it names. It also re-spaced the rows
   themselves, so a list's row rhythm changed the moment it gained a header. Rows inside a
   section are now parted by whatever parts rows in a section-less list, which is the root gap. */
.sd-list-box__section {
  display: flex;
  flex-direction: column;
  gap: var(--sd-list-box-gap);
}

/* ADJACENCY is an assumption, not a guarantee. React Aria's `Virtualizer` wraps each node in a
   `VirtualizerItem`, which would split this pair and silently drop the separation. Nothing under
   `src/**` uses it and no component exposes it, so nothing rendered is wrong; a cold review found
   no selector correct under both shapes at no cost, because spacing an absolutely positioned
   wrapper fights the virtualizer's own layout. Re-measure here first if virtualization is ever
   offered. */
.sd-list-box__section + .sd-list-box__section {
  margin-block-start: var(--sd-list-box-section-gap);
}

.sd-list-box__section-header {
  /* At 0 inline, on the start line the rows' content shares. */
  padding-block: var(--sd-list-box-section-header-padding-block-start) var(--sd-list-box-section-header-padding-block-end);
  color: var(--sd-list-box-section-header-foreground);
}

.sd-list-box__load-more {
  display: flex;
  justify-content: center;
  padding-block: var(--sd-list-box-load-more-padding-block);
  color: var(--sd-list-box-load-more-foreground);
}

.sd-list-box__item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-list-box-item-icon-size);
  width: var(--sd-list-box-item-icon-size);
  height: var(--sd-list-box-item-icon-size);
  font-size: var(--sd-list-box-item-icon-size);
}

/* A TWO-LINE option. React Aria keeps `slot` on each `Text`, so the item can lay the pair out
   without the consumer wrapping them: the description takes a full basis and drops to its own
   line, which leaves the icon and label on the first. Only reached when a description is present,
   so a one-line option is untouched. An icon does not indent the second line — no story composes
   that pair, and guessing at the inset would be building for a case with no example. */
.sd-list-box__item:has(> [slot="description"]) {
  flex-wrap: wrap;
  align-items: start;
}
.sd-list-box__item > [slot="description"] {
  flex-basis: 100%;
  color: var(--sd-list-box-item-description-current);
}

/* Raised to the row's own ink while it is hovered or pressed: this ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-list-box__item[data-hovered],
.sd-list-box__item[data-focused],
.sd-list-box__item[data-pressed] {
  --sd-list-box-item-description-current: var(--sd-list-box-item-foreground);
}

/* The empty-state message (`renderEmptyState`): its own text part, so it takes a type role and the
   text inset like every other text, in the supporting ink of an empty line. */
.sd-list-box__empty {
  color: var(--sd-list-box-empty-foreground);
}
